<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Course Progress | DevXcript Student Portal</title><link rel="icon" href="img/logo.png">
<link href="https://fonts.googleapis.com/css2?family=Onest:wght@100..900&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet">
<link href="css/style.css" rel="stylesheet"></head><body>
<aside class="sidebar" id="sidebar"><div class="p-3 border-bottom d-flex justify-content-between align-items-center"><div class="d-flex align-items-center gap-2"><div class="logo-box">DX</div><div><div class="fw-bold fs-5 lh-1">DevXcript</div><small class="text-muted">Student Portal</small></div></div><button class="btn btn-sm d-xl-none" id="closeSide"><i class="bi bi-x-lg"></i></button></div>
<nav class="p-3 d-grid gap-1"><a href="dashboard.html" class="nav-x"><i class="bi bi-grid fs-5"></i><span>Dashboard</span><i class="dot"></i></a><a href="courses.html" class="nav-x active"><i class="bi bi-book fs-5"></i><span>Courses</span><i class="dot"></i></a><a href="results.html" class="nav-x"><i class="bi bi-clipboard-check fs-5"></i><span>Results</span><i class="dot"></i></a><a href="datesheet.html" class="nav-x"><i class="bi bi-calendar3 fs-5"></i><span>Date Sheet</span><i class="dot"></i></a><a href="invoices.html" class="nav-x"><i class="bi bi-file-earmark-text fs-5"></i><span>Invoices</span><i class="dot"></i></a><a href="attendance.html" class="nav-x"><i class="bi bi-check2-square fs-5"></i><span>Attendance</span><i class="dot"></i></a></nav><div class="side-foot">Developed By DevXcript</div></aside><div class="overlay" id="overlay"></div>
<div class="main"><header class="topbar px-3 px-md-4 d-flex align-items-center justify-content-between">
<div class="d-flex align-items-center gap-3"><button class="btn btn-sm d-xl-none" id="openSide"><i class="bi bi-list fs-4"></i></button><h2 class="h5 fw-bold mb-0">Course Progress</h2></div>
<div class="d-flex align-items-center gap-2">
<div class="dropdown"><button class="btn position-relative" data-bs-toggle="dropdown"><i class="bi bi-bell"></i><span class="bell-dot"></span></button>
<div class="dropdown-menu dropdown-menu-end p-3" style="width:260px"><div class="d-flex justify-content-between mb-2"><b class="small">Notifications</b><span class="badge bg-light text-secondary">2</span></div>
<div class="p-2 rounded border mb-2" style="background:var(--teal-50);border-color:var(--teal-100)!important"><div class="small">Register for next semester</div><div class="small-x">2 min ago</div></div>
<div class="p-2 rounded bg-light"><div class="small">Fee challan available</div><div class="small-x">1 hour ago</div></div></div></div>
<div class="dropdown"><div class="d-flex align-items-center gap-2 px-2 py-1" role="button" data-bs-toggle="dropdown"><div class="avatar">BA</div><div class="d-none d-sm-block lh-sm"><div class="small fw-medium">Babar Azam</div><div class="small-x text-truncate" style="max-width:120px">babar@devxcript.com</div></div></div>
<ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item text-danger small" href="signin.html"><i class="bi bi-box-arrow-right me-2"></i>Logout</a></li></ul></div></div></header>
<main class="p-3 p-sm-4 p-lg-4"><div class="page-wrap"><a href="courses.html" class="text-decoration-none text-secondary d-inline-flex align-items-center gap-2 mb-3"><i class="bi bi-arrow-left"></i> Back to Courses</a><div id="detail"></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="js/main.js"></script><script>
const D={'web-application':['Web Application Development','CSSE3143','Asad Kamal','3.0',[['Class Participation',9,10],['Assignment',8,10],['Quiz',19,20],['Mids',17,20],['Final',32,40]]],
'software-engineering':['Introduction to Software Engineering','CSSE3113','Muhammad Basit Ali Gillani','3.0',[['Lab Exercise',7,10],['Assignment',6,10],['Quiz',16,20],['Midterm',15,20],['Final',25,40]]],
'operating-system':['Operating Systems','CSCS3553','Dr Adnan Ghafoor','3.0',[['Class Participation',9,10],['Assignment',8,10],['Quiz',19,20],['Mids',17,20],['Final',32,40]]],
'operating-system-lab':['Operating Systems - Lab','CSCS3551','Qaisar Aslam','1.0',[['Lab Exercise',8,10],['Assignment',7,10],['Quiz',17,20],['Midterm',14,20],['Final',28,40]]]};
const c=D[new URLSearchParams(location.search).get('id')],box=document.getElementById('detail');
if(!c){box.innerHTML='<div class="text-center py-5"><h2 class="fw-bold">Course Not Found</h2><p class="text-secondary">The requested course could not be found.</p><a href="courses.html" class="btn btn-theme">Back to Courses</a></div>'}
else{const o=c[4].reduce((s,x)=>s+x[1],0),t=c[4].reduce((s,x)=>s+x[2],0),p=o/t*100;
const g=p>=90?['A','green']:p>=80?['B','blue']:p>=70?['C','yellow']:p>=60?['D','orange']:['F','red'];
box.innerHTML=`<div class="box p-4 mb-3"><div class="row g-4 align-items-center"><div class="col-lg-6"><h1 class="h3 fw-bold mb-2">${c[0]}</h1><div class="fs-5 text-secondary mb-3">${c[1]}</div><div class="d-flex gap-4 small text-secondary"><span><i class="bi bi-person me-2"></i>${c[2]}</span><span><i class="bi bi-credit-card me-2"></i>${c[3]} Credits</span></div></div>
<div class="col-lg-6"><div class="row g-3"><div class="col-4"><div class="tile"><small>Total Score</small><b class="fs-4">${o}/${t}</b></div></div><div class="col-4"><div class="tile"><small>Percentage</small><b class="fs-4" style="color:var(--teal-600)">${p.toFixed(2)}%</b></div></div><div class="col-4"><div class="tile"><small>Grade</small><span class="pill pill-${g[1]} fs-4 fw-bold rounded-3">${g[0]}</span></div></div></div></div></div></div>
<div class="box overflow-hidden"><div class="table-responsive"><table class="table tbl mb-0"><thead class="thead-teal"><tr><th>Assessment Type</th><th class="text-center">Obtained Marks</th><th class="text-center">Total Marks</th><th class="text-center">Percentage</th></tr></thead><tbody>
${c[4].map(a=>{const x=a[1]/a[2]*100;return `<tr><td class="fw-medium">${a[0]}</td><td class="text-center fw-semibold" style="color:var(--teal-600)">${a[1]}</td><td class="text-center text-secondary">${a[2]}</td><td class="text-center fw-medium ${x>=50?'text-success':'text-danger'}">${x.toFixed(1)}%</td></tr>`}).join('')}
</tbody><tfoot class="table-light fw-bold"><tr><td>Total</td><td class="text-center" style="color:var(--teal-600)">${o}</td><td class="text-center">${t}</td><td class="text-center" style="color:var(--teal-600)">${p.toFixed(2)}%</td></tr></tfoot></table></div></div>`}
</script></body></html>